class ResolverVectorTests(unittest.TestCase):
    def test_seven_literal_closures_and_hashes(self):
        g,named=graph_fixture()
        self.assertEqual(7,len(VECTORS))
        for name,root,manifest,wire,sha in VECTORS:
            with self.subTest(vector=name):
                self.assertEqual(named[name],root)
                actual=resolve_si_closure(g.records,[root])
                self.assertEqual(manifest,actual)
                self.assertEqual(wire,canonical_si_json(actual))
                self.assertEqual(sha,hashlib.sha256(wire).hexdigest())

    def test_literals_independent_explicit_edge_oracle(self):
        g,named=graph_fixture()
        for name,root,manifest,wire,sha in VECTORS:
            with self.subTest(vector=name):
                self.assertEqual(manifest,g.closure([root]))
                self.assertEqual(sha,hashlib.sha256(wire).hexdigest())


if __name__=='__main__':unittest.main()
